class Gradebook:
    def __init__(self, set_missing_zero=False):
        self.set_missing_zero = set_missing_zero

def percent(self, student):
    total_points = 0
    total_max_points = 0
    for assignment, points in self.students[student].items():
        if points is None:
            if self.set_missing_zero:
                points = 0
            else:
                continue
        total_points += points
        total_max_points += self.assignments[assignment]
    return (total_points / total_max_points) * 100 if total_max_points > 0 else 0

